#include <string.h>

int total_energy(int cells[], int n) {
    int totalValueSoFar = 0;
    int i = 0;
    int flag = 0;
    while (i < n) {
        if (flag == 0) {
            totalValueSoFar = 0;
            flag = 1;
        } else {
            totalValueSoFar = totalValueSoFar + cells[i];
        }
        i = i + 1;
    }
    return totalValueSoFar;
}
